<?php
namespace Divigamana\Controllers;
use Divigamana\Support\{Database,Http,Session}; use Divigamana\Services\{ServiceCatalog,RahuKalaya,QwenProvider};
final class ApiController {
 private static function mobile(string $v): ?string { $n=preg_replace('/\D/','',$v);if(str_starts_with($n,'0'))$n='94'.substr($n,1);if(str_starts_with($n,'94')&&strlen($n)===11)return '+'.$n;return null; }
 private static function rate(string $key,int $seconds):bool { $now=time();if(($_SESSION['rate'][$key]??0)>$now-$seconds)return false;$_SESSION['rate'][$key]=$now;return true; }
 public static function rahu():never { Http::json(['ok'=>true,'rahu'=>RahuKalaya::today()]); }
 public static function auth():never { $i=Http::input();Http::requirePostCsrf($i);if((APP_CONFIG['app_env']??'production')!=='development')Http::json(['ok'=>false,'error'=>'Demo OTP is disabled. Configure a production SMS provider.'],503);$m=self::mobile((string)($i['mobile']??''));if(!$m)Http::json(['ok'=>false,'error'=>'Enter a valid Sri Lankan mobile number.'],422);if(empty($i['consent']))Http::json(['ok'=>false,'error'=>'Subscription consent is required.'],422);if(!self::rate('otp',30))Http::json(['ok'=>false,'error'=>'Please wait before requesting another code.'],429);$_SESSION['otp_mobile']=$m;$_SESSION['otp_consent']=true;$_SESSION['otp_demo_expires']=time()+600;Http::json(['ok'=>true,'message'=>'Development mode: enter any six-digit code. No SMS was sent.']); }
 public static function verify():never { $i=Http::input();Http::requirePostCsrf($i);if((APP_CONFIG['app_env']??'production')!=='development')Http::json(['ok'=>false,'error'=>'Demo OTP is disabled. Configure a production SMS provider.'],503);$code=(string)($i['otp']??'');$mobile=$_SESSION['otp_mobile']??null;if(!preg_match('/^\d{6}$/',$code)||!$mobile||empty($_SESSION['otp_consent'])||time()>($_SESSION['otp_demo_expires']??0))Http::json(['ok'=>false,'error'=>'Enter a valid six-digit demo code.'],422);$pdo=Database::pdo();$pdo->beginTransaction();try{$st=$pdo->prepare('SELECT * FROM users WHERE mobile_e164=? LIMIT 1');$st->execute([$mobile]);$u=$st->fetch();if(!$u){$pdo->prepare("INSERT INTO users (mobile_e164,otp_verified_demo,phone_verified_real,role) VALUES (?,1,0,'user')")->execute([$mobile]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO user_subscriptions (user_id,status,is_simulated,accepted_at,starts_at,ends_at) VALUES (?,'active',1,NOW(),NOW(),DATE_ADD(NOW(),INTERVAL 1 DAY))")->execute([$id]);$pdo->prepare("INSERT INTO consent_history (user_id,consent_type,consent_text,locale) VALUES (?,'simulated_subscription','Daily Rs. 8.00 + Tax simulated development subscription',?)")->execute([$id,$i['locale']??'si-LK']);$u=['id'=>$id,'mobile_e164'=>$mobile,'role'=>'user'];}else{$pdo->prepare('UPDATE users SET otp_verified_demo=1 WHERE id=?')->execute([$u['id']]);}$pdo->commit();Session::login($u);unset($_SESSION['otp_mobile'],$_SESSION['otp_consent']);Http::json(['ok'=>true,'user'=>Session::user(),'simulated'=>true]);}catch(\Throwable $e){$pdo->rollBack();Http::json(['ok'=>false,'error'=>'Could not complete sign in.'],500);} }
 public static function status():never { $u=Session::user();if(!$u)Http::json(['ok'=>true,'authenticated'=>false]);$s=Database::pdo()->prepare("SELECT status,is_simulated,ends_at FROM user_subscriptions WHERE user_id=? ORDER BY id DESC LIMIT 1");$s->execute([$u['id']]);$sub=$s->fetch();Http::json(['ok'=>true,'authenticated'=>true,'user'=>$u,'subscribed'=>$sub&&$sub['status']==='active'&&$sub['ends_at']>date('Y-m-d H:i:s'),'subscription'=>$sub]); }
 public static function generate():never { $i=Http::input();Http::requirePostCsrf($i);$u=Session::user();if(!$u)Http::json(['ok'=>false,'error'=>'Please sign in first.'],401);$service=ServiceCatalog::find((string)($i['service']??''));if(!$service)Http::json(['ok'=>false,'error'=>'Service not found.'],404);$p=Database::pdo();$sub=$p->prepare("SELECT id FROM user_subscriptions WHERE user_id=? AND status='active' AND ends_at>NOW() LIMIT 1");$sub->execute([$u['id']]);if(!$sub->fetch())Http::json(['ok'=>false,'error'=>'An active subscription is required.'],403);$answers=is_array($i['answers']??null)?$i['answers']:[];foreach($service['fields'] as $f){$v=trim((string)($answers[$f['name']]??''));if($f['required']&&$v==='')Http::json(['ok'=>false,'error'=>'Please complete: '.str_replace('_',' ',$f['name'])],422);$answers[$f['name']]=mb_substr(strip_tags($v),0,2500);}$idem=(string)($i['idempotency_key']??'');if(!preg_match('/^[a-zA-Z0-9-]{16,100}$/',$idem))Http::json(['ok'=>false,'error'=>'Invalid request identifier.'],422);$existing=$p->prepare('SELECT r.result_json FROM horoscope_requests q JOIN horoscope_results r ON r.request_id=q.id WHERE q.user_id=? AND q.idempotency_key=?');$existing->execute([$u['id'],$idem]);if($row=$existing->fetch())Http::json(['ok'=>true,'result'=>json_decode($row['result_json'],true),'cached'=>true]);$p->beginTransaction();try{$p->prepare("INSERT INTO horoscope_requests (user_id,service_id,status,locale,questionnaire_json,idempotency_key) VALUES (?,?, 'processing',?,?,?)")->execute([$u['id'],$service['id'],$i['locale']??'si-LK',json_encode($answers,JSON_UNESCAPED_UNICODE),$idem]);$rid=(int)$p->lastInsertId();if($service['paid'])$p->prepare("INSERT INTO payment_transactions (user_id,request_id,amount,currency,status,is_simulated,description) VALUES (?,?,20,'LKR','simulated_confirmed',1,'Simulated per-reading charge')")->execute([$u['id'],$rid]);$p->commit();$out=(new QwenProvider)->generate($service,$answers,$i['locale']??'si-LK');$p->prepare("INSERT INTO horoscope_results (request_id,result_json,model_name) VALUES (?,?,?)")->execute([$rid,json_encode($out['result'],JSON_UNESCAPED_UNICODE),$out['model']]);$p->prepare("UPDATE horoscope_requests SET status='completed',completed_at=NOW() WHERE id=?")->execute([$rid]);$p->prepare('INSERT INTO ai_usage_logs (request_id,model_name,total_tokens,duration_ms) VALUES (?,?,?,?)')->execute([$rid,$out['model'],$out['tokens'],$out['duration_ms']]);Http::json(['ok'=>true,'result'=>$out['result'],'request_id'=>$rid,'simulated_charge'=>$service['paid']]);}catch(\Throwable $e){if($p->inTransaction())$p->rollBack();if(isset($rid))$p->prepare("UPDATE horoscope_requests SET status='failed' WHERE id=?")->execute([$rid]);error_log($e->getMessage());Http::json(['ok'=>false,'error'=>'We could not generate this reading just now. Please try again.'],503);} }
}
